def test_runtime_fail_closed_temporal_combat_authority():
 s=read('scripts/online/m270_authoritative_combat_state_runtime.gd')
 for t in ['bind_combat','ingest_server_combat_state','ingest_server_state_event','stage_local_projectile_visual','local_reload_display','combat_state_revision','active_status_effects','active_projectiles','invalidate_from_world_resync']: assert t in s
