 m=load('data/m239_master_convergence_matrix.json'); assert m['milestone'] in {'M270','M271','M272','M273','M274','M275','M276','M277','M278','M279','M280','M281','M282','M283','M284','M285','M286','M287','M288','M289','M290','M291','M292','M293','M294','M295','M296','M297','M298','M299','M300','M301'}; row={x['domain']:x for x in m['domains']}['authoritative_combat_state_reload_status_projectile_resolution']; assert row['status']=='PARTIAL' and 'm270_fix' in row and 'production projectile simulation/collision/impact service' in row['remaining']
 c=load('data/m270_authoritative_combat_state_contract.json'); assert c['dependencies']['combat_resolution'].startswith('M269') and c['dependencies']['world_transport'].startswith('M267') and c['dependencies']['economy_inventory'].startswith('M266')
